import hashlib,json,os,datetime
from pathlib import Path
assert Path('/proc/sys/kernel/random/boot_id').read_text().strip()=='903cfade-b93c-48fa-804e-379be1967313'
def txt(p):
 try:return Path(p).read_text().strip()
 except OSError as e:return {'error_type':type(e).__name__}
roots={}
for name in ('/sys/kernel/config/device-tree/overlays','/sys/class/fpga_manager/fpga0','/sys/class/fpga_region','/sys/bus/platform/drivers/zocl','/sys/class/drm'):
 p=Path(name)
 roots[name]={'exists':p.exists(),'children':[]}
 if p.exists():
  for q in sorted(p.iterdir()):
   row={'name':q.name,'symlink':q.is_symlink()}
   if q.is_symlink():row['target']=os.readlink(q)
   if name.endswith('/overlays') and q.is_dir():
    row['attributes']={k:txt(q/k) for k in ('status','path') if (q/k).exists()}
   if name.endswith('/fpga0') and q.name in ('state','name','flags','firmware'):row['value']=txt(q)
   roots[name]['children'].append(row)
dtnodes=[]
for p in Path('/proc/device-tree').rglob('*'):
 if not p.is_dir():continue
 c=p/'compatible'
 if c.is_file():
  data=c.read_bytes()
  if b'zocl' in data or b'xlnx,fpga' in data or b'dpu' in data:
   row={'path':str(p),'compatible':data.decode(errors='replace').replace('\0','|')}
   for k in ('status','firmware-name'):
    q=p/k
    if q.exists():row[k]=q.read_bytes().decode(errors='replace').replace('\0','|')
   dtnodes.append(row)
print(json.dumps({'boot_id':Path('/proc/sys/kernel/random/boot_id').read_text().strip(),'board_utc':datetime.datetime.now(datetime.timezone.utc).isoformat(),'roots':roots,'dt_nodes':dtnodes,'fdt_sha256':hashlib.sha256(Path('/sys/firmware/fdt').read_bytes()).hexdigest(),'vart':txt('/etc/vart.conf'),'board_mutations':False}))
